DROP TABLE IF EXISTS `articles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `articles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL COMMENT '文章标题',
  `title_en` varchar(255) DEFAULT NULL COMMENT '英文标题',
  `category` varchar(50) DEFAULT '默认',
  `summary` text COMMENT '文章摘要(未付费看这里)',
  `summary_en` text COMMENT '英文摘要',
  `content` longtext,
  `content_en` longtext COMMENT '英文内容',
  `cover` varchar(255) DEFAULT NULL,
  `cover_image` varchar(255) DEFAULT NULL COMMENT '封面图路径',
  `is_paid` tinyint(1) DEFAULT '0' COMMENT '是否收费: 0免费, 1收费',
  `price` decimal(10,2) DEFAULT '0.00' COMMENT '价格',
  `tags` varchar(255) DEFAULT NULL COMMENT '标签，逗号分隔',
  `views` int(11) DEFAULT '0' COMMENT '阅读量',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `verify_code` varchar(50) DEFAULT NULL COMMENT '解锁验证码',
  `resource_content` text COMMENT '隐藏的资源内容',
  `point_price` int(11) DEFAULT '0' COMMENT '积分价格(0不启用)',
  `free_level_id` int(11) DEFAULT '0' COMMENT '对此等级及以上免费',
  `is_recommend` tinyint(1) DEFAULT '0',
  `is_top` bigint(20) DEFAULT '0' COMMENT '置顶时间戳(0为不置顶)',
  `type` varchar(20) DEFAULT 'wallpaper' COMMENT 'wallpaper or article',
  `attachment_url` varchar(255) DEFAULT NULL COMMENT '本地上传的文件路径',
  `price_usd` decimal(10,2) DEFAULT '0.00' COMMENT '美元价格',
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_is_paid` (`is_paid`),
  FULLTEXT KEY `idx_fulltext_title` (`title`,`summary`),
  FULLTEXT KEY `idx_title_fulltext` (`title`)
) ENGINE=InnoDB AUTO_INCREMENT=67 DEFAULT CHARSET=utf8mb4 COMMENT='文章主表';
