CREATE TABLE `user_resources` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `article_id` int(11) DEFAULT '0' COMMENT '原始文章ID，文章删了也没事',
  `saved_title` varchar(255) NOT NULL COMMENT '购买时的标题快照',
  `saved_content` text NOT NULL COMMENT '购买时的网盘链接快照',
  `source_type` varchar(20) DEFAULT 'buy' COMMENT 'buy:购买, code:兑换',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4;
