--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL COMMENT '加密后的密码',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像URL',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `login_ip` varchar(50) DEFAULT NULL COMMENT '登录IP',
  `user_agent` varchar(500) DEFAULT NULL COMMENT '设备UA标识',
  `last_login` datetime DEFAULT NULL COMMENT '最后活跃时间',
  `email` varchar(100) DEFAULT NULL,
  `is_email_verified` tinyint(1) DEFAULT '0' COMMENT '0未认证 1已认证',
  `can_comment` tinyint(1) DEFAULT '1' COMMENT '1允许评论 0禁言',
  `is_banned` tinyint(1) DEFAULT '0' COMMENT '0正常 1封号',
  `unique_id` varchar(64) NOT NULL COMMENT '唯一哈希标识',
  `nickname` varchar(50) DEFAULT NULL,
  `balance` decimal(10,2) DEFAULT '0.00' COMMENT '余额',
  `points` int(11) DEFAULT '0' COMMENT '积分',
  `vip_expire` datetime DEFAULT NULL COMMENT 'VIP过期时间',
  `last_checkin_date` date DEFAULT NULL COMMENT '最后签到日期',
  `vip_level_id` int(11) DEFAULT '1' COMMENT '对应vip_levels的id',
  `consecutive_days` int(11) DEFAULT '0',
  `vip_level` tinyint(4) DEFAULT '0' COMMENT '0:普通, 1:黄金, 2:钻石',
  `last_checkin` date DEFAULT NULL,
  `token` varchar(64) DEFAULT NULL,
  `last_ip` varchar(50) DEFAULT NULL,
  `device_info` varchar(255) DEFAULT NULL,
  `email_verified` tinyint(1) DEFAULT '0' COMMENT '邮箱是否验证',
  `checkin_streak` int(11) DEFAULT '0' COMMENT '连续签到天数',
  `register_ip` varchar(50) DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  KEY `idx_username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `users`
--

LOCK TABLES `users` WRITE;
