--
-- Table structure for table `vip_levels`
--

DROP TABLE IF EXISTS `vip_levels`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vip_levels` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '等级名称 (如 白银会员)',
  `discount` decimal(3,2) DEFAULT '1.00' COMMENT '折扣率 (0.70 表示7折, 1.00 原价)',
  `is_super` tinyint(1) DEFAULT '0' COMMENT '是否全站免费 (1是, 0否)',
  `level_weight` int(11) DEFAULT '0' COMMENT '权重 (用于比较等级高低，数字越大越高级)',
  `price_month` decimal(10,2) DEFAULT '0.00' COMMENT '月费参考价',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

