DROP TABLE IF EXISTS `vip_plans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vip_plans` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '套餐名',
  `name_en` varchar(100) DEFAULT NULL COMMENT '英文套餐名',
  `days` int(11) NOT NULL COMMENT '天数',
  `price` decimal(10,2) NOT NULL COMMENT '价格',
  `price_usd` decimal(10,2) DEFAULT '0.00' COMMENT '美元价格',
  `style_color` varchar(20) DEFAULT '#00FFFF' COMMENT '卡片颜色',
  `level_id` int(11) DEFAULT '0' COMMENT '对应vip_levels.id',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4;
